func pop[T any](stack []T) ([]T, T, bool) {
    if len(stack) == 0 { var zero T; return stack, zero, false }
    i := len(stack) - 1
    value := stack[i]
    var zero T
    stack[i] = zero
    return stack[:i], value, true
}
